57	    const key = cacheKey(cwd, options);
58	    const cached = scans.get(key);
59	    if (cached && !isStale(cached, filename)) {
60	        return { key, entry: cached };
61	    }
62	    const entry = scan(cwd, options);
63	    scans.set(key, entry);
64	    return { key, entry };
65	}
66	function reportUnavailable(context, key, error) {
67	    if (reportedUnavailable.has(key)) {
68	        return;
69	    }
70	    reportedUnavailable.add(key);
71	    context.report({
72	        loc: { line: 1, column: 0 },
73	        messageId: "unavailable",
74	        data: { error },
75	    });
76	}
