/** Resolves once a condition holds, polling every ten milliseconds for up to half a second. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** Terminates every socket a suite holds, waits until each server has seen its sockets close, then stops the servers. */
export async function drainAndStop(clients: WebSocket[], servers: HalServer[]): Promise<void> {
  for (const client of clients.splice(0)) client.terminate();
  for (const hal of servers.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the members every store must have, so an optional one can be added or left out per test. */
export function delegatingTo(inner: InMemorySessionStore): SessionStore {
